// Form data extract karo
const city = $input.first().json['City / State'] || '';
const country = $input.first().json['Country'] || '';
const niche = $input.first().json['Niche / Industry'] || '';
const customQuestions = $input.first().json['Custom Questions'] || '';
const sourcesChoice = $input.first().json['Sources to Search'] || 'Reddit Only';

// Reddit search query build karo
const redditQuery = encodeURIComponent(`${niche} ${city} ${country}`);
const redditUrl = `https://www.reddit.com/search.json?q=${redditQuery}&sort=relevance&limit=10&type=link`;

// Source URLs build karo
const linkedinUrl = `https://www.linkedin.com/search/results/companies/?keywords=${encodeURIComponent(`${niche} ${city}`)}` ;
const googleMapsUrl = `https://www.google.com/maps/search/${encodeURIComponent(`${niche} ${city} ${country}`)}`;
const facebookUrl = `https://www.facebook.com/search/pages/?q=${encodeURIComponent(`${niche} ${city}`)}`;
const yelpUrl = `https://www.yelp.com/search?find_desc=${encodeURIComponent(niche)}&find_loc=${encodeURIComponent(`${city} ${country}`)}`;

// Custom questions parse karo
const questionsList = customQuestions
  .split('\n')
  .map(q => q.trim())
  .filter(q => q.length > 0);

// Timestamp
const timestamp = new Date().toISOString();

return [
  {
    json: {
      city,
      country,
      niche,
      customQuestions: questionsList,
      customQuestionsRaw: customQuestions,
      sourcesChoice,
      redditUrl,
      redditQuery: decodeURIComponent(redditQuery),
      linkedinUrl,
      googleMapsUrl,
      facebookUrl,
      yelpUrl,
      timestamp
    }
  }
];

// Reddit response parse karo
const redditData = $input.first().json;
const posts = redditData?.data?.children || [];

// Previous node ka data lo
const prevData = $('Build Search Data').first().json;

// Reddit posts format karo
const formattedPosts = posts.slice(0, 10).map((post, index) => {
  const p = post.data;
  return {
    index: index + 1,
    title: p.title || '',
    subreddit: p.subreddit_name_prefixed || '',
    url: `https://reddit.com${p.permalink}` || '',
    score: p.score || 0,
    numComments: p.num_comments || 0,
    author: p.author || '',
    created: new Date(p.created_utc * 1000).toLocaleDateString()
  };
});

// Top 5 posts summary for sheets
const top5Summary = formattedPosts.slice(0, 5)
  .map(p => `${p.index}. ${p.title} (${p.subreddit}) — ${p.url}`)
  .join('\n');

// Custom questions as string
const questionsStr = prevData.customQuestions.length > 0
  ? prevData.customQuestions.map((q, i) => `Q${i+1}: ${q}`).join('\n')
  : 'No custom questions provided';

return [
  {
    json: {
      // Sheet mein jane wala data
      Timestamp: prevData.timestamp,
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Sources Selected': prevData.sourcesChoice,
      'Custom Questions': questionsStr,
      'Reddit Posts Found': formattedPosts.length,
      'Top Reddit Results': top5Summary,
      'Reddit Search URL': prevData.redditUrl,
      'LinkedIn URL': prevData.linkedinUrl,
      'Google Maps URL': prevData.googleMapsUrl,
      'Facebook URL': prevData.facebookUrl,
      'Yelp URL': prevData.yelpUrl,
      // Extra metadata
      _allPosts: JSON.stringify(formattedPosts),
      _redditQuery: prevData.redditQuery
    }
  }
];
